class Solution {
public:
    vector<int> assignTasks(vector<int>& servers, vector<int>& tasks) {
        int n = servers.size();
        int m = tasks.size();

        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> avail;
        priority_queue<tuple<long long,int,int>, vector<tuple<long long,int,int>>, greater<tuple<long long,int,int>>> busy;

        for (int i = 0; i < n; i++) {
            avail.push({servers[i], i});
        }

        vector<int> ans(m);
        long long time = 0;

        for (int j = 0; j < m; j++) {
            time = max(time, (long long)j);

            while (!busy.empty() && get<0>(busy.top()) <= time) {
                avail.push({get<1>(busy.top()), get<2>(busy.top())});
                busy.pop();
            }

            if (avail.empty()) {
                time = get<0>(busy.top());
                while (!busy.empty() && get<0>(busy.top()) <= time) {
                    avail.push({get<1>(busy.top()), get<2>(busy.top())});
                    busy.pop();
                }
            }

            auto best = avail.top();
            avail.pop();
            ans[j] = best.second;
            busy.push({time + tasks[j], best.first, best.second});
        }

        return ans;
    }
};
